/**
 * Novus OS - packed Unicode glyph blob.
 *
 * nd_font_data.bin is generated by tools/fontgen/fontgen.py from GNU Unifont
 * and committed: the build needs neither the Unifont sources nor a host font.
 * incbin keeps 3.5 MiB of bitmap data out of the C compiler's input.
 */

    .section .rdata,"dr"
    .globl g_font_data
    .balign 16
g_font_data:
    .incbin "graphics/nd_font_data.bin"
